actions.script:
const support=ec.resource.script('component://mr-pass/screen/Support/Support.js'),p=ec.web.parameters
const orderId=support.param('orderId')
const lines=Object.keys(p).filter(k=>/^return_[A-Za-z0-9]{1,20}$/.test(k)).map(k=>{const seq=k.slice(7)
    return {orderItemSeqId:seq,quantity:support.param('quantity_'+seq),returnReasonEnumId:support.param('reason_'+seq),
        returnResponseEnumId:support.param('remedy_'+seq),condition:support.param('condition_'+seq)}})
support.post('requestCustomerReturn',{siteId:resolvedSiteId,orderId,lines:JSON.stringify(lines),customerReference:support.param('customerReference'),
    note:support.param('note'),file:support.file(),operationId:support.param('operationId')},{path:support.base(publicPath,'submit'),params:{orderId}},
    result=>({path:passBases.support+'/CustomerReturn',params:{returnId:result.returnId}}))
